import { describe, it, expect } from "vitest";
import { createFreeCamera, enableOrthographicCamera } from "@babylonjs/lite";
import { labelPosition } from "./label-position.ts";

const canvas = { width: 800, height: 600, clientWidth: 400, clientHeight: 300 } as unknown as HTMLCanvasElement;

describe("labelPosition", () => {
    it("perspective", () => {
        const cam = createFreeCamera({ x: 0, y: 0, z: 0 }, { x: 0, y: 0, z: 10 });
        console.log("near/far/fov", cam.nearPlane, cam.farPlane, cam.fov);
        const c = labelPosition(cam, canvas, { x: 0, y: 0, z: 10 });
        console.log("center", c);
        expect(c.visible).toBe(true);
        expect(c.x).toBeCloseTo(200); expect(c.y).toBeCloseTo(150);
        const b = labelPosition(cam, canvas, { x: 0, y: 0, z: -10 });
        console.log("behind", b); expect(b.visible).toBe(false);
        const far = labelPosition(cam, canvas, { x: 0, y: 0, z: cam.farPlane * 50 });
        console.log("far", far); expect(far.visible).toBe(true);
        const right = labelPosition(cam, canvas, { x: 1000, y: 0, z: 10 });
        console.log("right", right); expect(right.visible).toBe(false); expect(right.x).toBeGreaterThan(400);
        const nan = labelPosition(cam, canvas, { x: NaN, y: 0, z: 10 });
        console.log("nan", nan); expect(nan.visible).toBe(false);
    });
    it("floating origin", () => {
        const cam = createFreeCamera({ x: 1e6, y: 0, z: 0 }, { x: 1e6, y: 0, z: 10 });
        cam._useFloatingOrigin = true;
        const c = labelPosition(cam, canvas, { x: 1e6, y: 0, z: 10 });
        console.log("fo center", c); expect(c.visible).toBe(true); expect(c.x).toBeCloseTo(200, 3);
    });
    it("orthographic", () => {
        const cam = createFreeCamera({ x: 0, y: 0, z: 0 }, { x: 0, y: 0, z: 10 });
        enableOrthographicCamera(cam, {});
        const behind = labelPosition(cam, canvas, { x: 0, y: 0, z: -10 });
        console.log("ortho behind", behind); expect(behind.visible).toBe(false);
        const front = labelPosition(cam, canvas, { x: 0, y: 0, z: 10 });
        console.log("ortho front", front); expect(front.visible).toBe(true);
    });
});
EOF
